import { createEvent } from '@testing-library/react';

const pristineCreateEvent = { ...createEvent };

// Patch createEvent to replace event type 'mouse' with 'pointer' for events relevant for the 'useDrag' hook.
export function patchCreateEvent() {
  for (const key in createEvent) {
    if (key.indexOf('mouse') === 0) {
      const fn = createEvent[key];
      if (!fn) {
        continue;
      }

      createEvent[key] = function (
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        type: any,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        { pointerId = 1, pointerType = 'mouse', ...rest }: any = {},
      ) {
        const event = fn(type, rest);
        event.pointerId = pointerId;
        event.pointerType = pointerType;
        const eventType = event.type.replace('mouse', 'pointer');
        Object.defineProperty(event, 'type', {
          get: function () {
            return eventType;
          },
        });
        return event;
      };
    }
  }
}

export function clearCreateEvent() {
  for (const key in createEvent) {
    if (key.indexOf('mouse') === 0) {
      createEvent[key] = pristineCreateEvent[key];
    }
  }
}
